  selector: 'app-example',
  template: `
    <h1>{{ myVariable }}</h1>
  `
})
export class ExampleComponent {
  myVariable = 'My Heading';
}
```
In the above example, the `myVariable` property is declared in the component and is used in the template using interpolation. The text of the `<h1>` element will be set to the value of `myVariable`.

You can also use the `{{ }}` syntax to dynamically set the value of `myVariable` in the template. For example:
```python
import { Component } from '@angular/core';

@Component({
  selector: 'app-example',
  template: `
    <h1>{{ myVariable }}</h1>
    <button (click)="changeMyVariable()">Change my variable</button>
  `
})
