```python
import { Component } from '@angular/core';

@Component({
  selector: 'app-example',
  template: `
    <h1 class="{{ isRed ? 'red' : '' }}">My Heading</h1>
    <p class="{{ isRed ? 'red' : '' }}">This text will be red if myVariable is true.</p>
  `
})
export class ExampleComponent {
  myVariable = false;
  constructor() {
    this.isRed = false;
  }

