```python
import os
import stat
import psutil

def find_largest_files_and_folders(top_count=10):
    # Get the total size of the filesystem
    total_size = psutil.disk_usage('/').total

    # Function to find the largest files
    def largest_files(top_count=top_count):
        candidates = []
        for entry in os.scandir():
            if entry.is_file():
                file_size = entry.stat().st_size
                if file_size > 0:
                    candidates.append((file_size, entry.name))
        return max(candidates, key=lambda x: x[0])[1]

    # Find the largest files
    largest_files = largest_files(top_count)
    for i, file in enumerate(largest_files):
        print(f"{i + 1}. {file} ({largest_files[i][0]} bytes)")

    # Find the largest folders
    def largest_folders(top_count=top_count):
        candidates = []
        for entry in os.scandir():
            if entry.is_dir():
                folder_size = psutil.disk_usage(entry.path).total
                if folder_size > 0:
                    candidates.append((folder_size, entry.name))
        return max(candidates, key=lambda x: x[0])[1]

    largest_folders = largest_folders(top_count)
    for i, folder in enumerate(largest_folders):
        print(f"{i + 1}. {folder} ({largest_folders[i][0]} bytes)")

