  newSnake[tail][1] = direction;
  newSnake[head][2] = direction;
  newSnake[tail][2] = direction;
  head++;
  tail++;
  if (head >= width || tail >= height) {
    head = 0;
    tail = width * height;
  }
  snake = newSnake;
  head = 0;
  tail = width * height;
}

function draw() {
