      let newX = i * width;
      let newY = j * height;
      switch (direction) {
        case 'up':
          newY -= direction;
          break;
        case 'down':
          newY += direction;
          break;
        case 'left':
          newX -= direction;
          break;
        case 'right':
          newX += direction;
          break;
        default:
          break;
      }
      console.log(newX + ',' + newY);
    }
  }
}

