```python
import numpy as np

class VoxelGrid:
    def __init__(self, resolution):
        self.resolution = resolution
        self.grid = self.create3DGrid(resolution)
        self.colors = np.zeros_like(self.grid)

    def create3DGrid(self, resolution):
        x = np.linspace(-2, 2, resolution)
        y = np.linspace(-2, 2, resolution)
        z = np.linspace(-2, 2, resolution)
        return np.meshgrid(x, y, z, indexing='ij')

    def iterateVoxels(self, julia_set):
        for i in range(self.resolution):
            for j in range(self.resolution):
                for k in range(self.resolution):
                    escape_time = julia_set.escapeTime(self.grid[0][i][j][k], self.grid[1][i][j][k], self.grid[2][i][j][k])
                    self.colors[i][j][k] = escape_time

    def colorVoxels(self, colormap):
        normalized_colors = self.colors / self.colors.max()
        return colormap(normalized_colors)
```

