    # Step 1: Permute the corners
    for i in range(4):
        for j in range(4):
            if i != j:
                moves.append(f"{i} {j} {i} {j}")

    # Step 2: Permute the edges
    for i in range(4):
        for j in range(4):
            if i != j:
                moves.append(f"{i} {j} {i} {j} {i} {j}")

    # Step 3: Permute the corners and edges
    for i in range(4):
        for j in range(4):
            if i != j:
                moves.append(f"{i} {j} {i} {j} {i} {j}")

