class Quaternion:
    def __init__(self, a, b, c, d):
        self.a, self.b, self.c, self.d = a, b, c, d

    def __add__(self, other):
        return Quaternion(self.a + other.a, self.b + other.b, self.c + other.c, self.d + other.d)

    def __mul__(self, other):
        a, b, c, d = self.a, self.b, self.c, self.d
        e, f, g, h = other.a, other.b, other.c, other.d
        return Quaternion(a * e - b * f - c * g - d * h, a * f + b * e + c * h - d * g, a * g - b * h + c * e + d * f, a * h + b * g - c * f + d * e)

    def norm(self):
        return np.sqrt(self.a**2 + self.b**2 + self.c**2 + self.d**2)

def create_3d_grid(grid_size, grid_step):
    grid_range = np.arange(-grid_size / 2, grid_size / 2, grid_step)
    return np.array([Quaternion(0, x, y, z) for x in grid_range for y in grid_range for z in grid_range])

def julia_iteration(q, c, max_iter):
    for i in range(max_iter):
        q = q * q + c
        if q.norm() > 2:
            return i
    return max_iter

