class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_NAME_1 = NAME_1(data)
        if not self.head:
            self.head = new_NAME_1
            return

        current = self.head
        while current.next:
            current = current.next
        current.next = new_NAME_1

    def insert(self, data, position):
        new_NAME_1 = NAME_1(data)
        if position == 0:
            new_NAME_1.next = self.head
            self.head = new_NAME_1
            return

        current = self.head
        prev = None
        for _ in range(position):
            if not current:
                raise IndexError("Position out of range")
            prev = current
            current = current.next

        prev.next = new_NAME_1
        new_NAME_1.next = current

    def delete(self, data):
        current = self.head
        prev = None

        while current:
            if current.data == data:
                if prev:
                    prev.next = current.next
                else:
                    self.head = current.next
                return
            prev = current
            current = current.next

        raise ValueError("Data not found in the list")

    def length(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

