import graphviz

def create_digraph_from_df(df, out_file=None):
    # create a dictionary of nodes and their outgoing edges
    nodes = {}
    edges = {}
    for index, row in df.iterrows():
        source = row["source"]
        target = row["target"]
        edges[source] = [target]
        nodes[target] = None
        nodes[source] = index

    # write the graph to a dot file
    graphviz_dot = """
digraph G {
    rankdir=LR;
    node [shape=box, style=filled, fillcolor=lightblue];
    edge [dir=none, arrowhead=none];
    """
    for node, edges_to in nodes.items():
        for target in edges_to:
            dot_str = f"{node} -> {target};"
            graphviz_dot += dot_str
    if out_file:
        with open(out_file, "w") as f:
            f.write(graphviz_dot)
    else:
        print(graphviz_dot)
