```python
def factorial(n):
    if n < 0:
        raise ValueError("Factorial cannot be negative")
    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 3
    else:
        result = 1
        for i in range(1, n):
            result *= i
        return result

```

