Here is a Python implementation of a dynamic programming algorithm to rephrase one text to match another text based on edit distance:

```python
import numpy as np

def levenshtein_distance(s1, s2):
    dist = np.zeros((len(s1) + 1, len(s2) + 1))

    for i in range(len(s1) + 1):
        dist[i][0] = i

    for j in range(len(s2) + 1):
        dist[0][j] = j

    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            if s1[i-1] == s2[j-1]:
                substitution_cost = 0
            else:
                substitution_cost = 1

            dist[i][j] = min(dist[i-1][j] + 1,        # deletion
                             dist[i][j-1] + 1,        # insertion 
                             dist[i-1][j-1] + substitution_cost) # substitution

    return dist

def rephrase(s1, s2):
    dist = levenshtein_distance(s1, s2)
    i = len(s1)
    j = len(s2)
    new_s1 = []

    while i > 0 or j > 0:
        if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
            new_s1.append(s1[i-1])
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dist[i][j] == dist[i-1][j] + 1):
            i -= 1
        elif j > 0 and (i == 0 or dist[i][j] == dist[i][j-1] + 1):
            new_s1.append(s2[j-1]) 
            j -= 1
        else:
            new_s1.append(s2[j-1])
            i -= 1
            j -= 1

    return "".join(reversed(new_s1))
```

This computes the edit distance matrix between the two texts, then traces back the optimal path to construct a new text that minimizes the edit distance. It performs insertion, deletion, and substitution edits as needed

