std::vector<std::vector<int>> fibonacci_matrix_multiplication(int n) {
    std::vector<std::vector<int>> A = {{1, 1}, {1, 0}};
    std::vector<std::vector<int>> B = {{1, 1}, {0, 1}};
    std::vector<std::vector<int>> F(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE, 0));

