def lcs(str1, str2):
    m, n = len(str1), len(str2)
    dp = [[0] * (n+1) for _ in range(m+1)] # dp[i][j] is the LCS of str1[:i] and str2[:j]
    for i in range(m+1):
        for j in range(n+1):
