data = [1, 0, 1, 0, 1, 0, 1] 
codeword = encode(data)  # [1, 0, 1, 0, 1, 1, 0, 1]
decoded = decode(codeword) # [1, 0, 1, 0, 1

Hamming code can be used to encode and decode integer data as well. Here is how it can be implemented for 32-bit integers:

```python
def encode(data):
    # Calculate number of parity bits needed
    m = 32  # 32 data bits
    p = 0
    while 2**p < m + p + 1:
        p += 1  # 7 parity bits needed

    # Add parity bits
    codeword = 0
    for i in range(m):
        codeword |= (data & 1) << i
        data >>= 1

    # Calculate parity bits
    for i in range(p):
        parity_bit = 0
        for j in range(m):
            if (j + 1) & (2**i) != 0:
                parity_bit ^= (codeword >> j) & 1
        codeword |= (parity_bit << (m + i))

    return codeword

def decode(codeword):
    # Check if single-bit error
    error = 0
    for i in range(p):
        parity_bit = 0
        for j in range(m + p):
            if (j + 1) & (2**i) != 0:
                parity_bit ^= (codeword >> j) & 1
        if parity_bit == 1:
            error += 1

    # If single-bit error, correct it
    if error == 1: 
        for i in range(p):
            parity_bit = 0
            for j in range(m + p):
                if (j + 1) & (2**i) != 0:
                    parity_bit ^= (codeword >> j) & 1
            if parity_bit == 1:
                codeword ^= (1 << i)

    # Remove parity bits        
    data = 0
    for i in range(m):
        data |= (codeword & 1) << i
        codeword >>= 1

    return data
```

