```cpp
#include <iostream>
#include <algorithm>
using namespace std;

// Returns the largest increasing subsequence of a given array
int largestIncreasingSubsequence(int arr[], int n) {
    int L[n], R[n];
    for (int i = 0; i < n; i++) {
        L[i] = 0, R[i] = 0;
    }
    L[0] = arr[0];
    R[0] = arr[0];
    for (int i = 1; i < n; i++) {
        int max_L = L[i-1];
        int max_R = R[i-1];
        if (max_L > max_R) L[i] = max_L, R[i] = max_R;
        else R[i] = max_L, L[i] = max_R;
    }
    return R[n-1];
}

int main() {
    int arr[] = {1, 2, 3, 2, 1};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Largest Increasing Subsequence: " << largestIncreasingSubsequence(arr, n) << endl;
    return 0;
}
```
The function uses adynamic programmingapproach to find the LIS of the given array. It initializes two arrays, L and R, to store the maximum increasing subsequences that begin at each index of the array. It then iterates over the array and compares the maximum increasing subsequence that can be formed by starting at each index with the previous maximum increasing subsequence. The function returns the maximum of the two as the LIS.

