namespace WavToWmaConverter
{
    class Program
    {
        static void Main(string[] args)
        {
            string inputFile = "input.wav";
            string outputFile = "output.wma";

            // Create the input and output media types
            AudioEncodingProperties inputFormat = AudioEncodingProperties.CreateWav(AudioStreamType.WavFile);
            AudioEncodingProperties outputFormat = AudioEncodingProperties.CreateWma(AudioStreamType.WmaFile);

            // Create the transcoder
            Transcoder transcoder = new Transcoder();

            // Add the input and output
            transcoder.AddInput(inputFile, inputFormat);
            transcoder.AddOutput(outputFile, outputFormat); 

            // Transcode!
            transcoder.TranscodeAsync().GetResults();

            Console.WriteLine("Conversion complete!");
        }
    }
}
```

