    dist_matrix = [[float("inf")] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                dist_matrix[i][j] = min(dist_matrix[i][j], connections[i][j])
    min_distance_matrix = [[parking_lot_capacity] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        min_distance_matrix[i] = [min(min_distance_matrix[i][j] + dist_matrix[i][j], min_distance_matrix[i+1][j]) for j in range(n)]
