```python
import pytest

@pytest.fixture(scope='module')
def test_fixure_1(request):
    # Test fixture
    request.add_marker(pytest.mark.last)

@pytest.fixture(scope='module')
def test_fixure_2(request):
    # Test fixture
    request.add_marker(pytest.mark.last)

def pytest_collection_modify(session, config):
    # Modify test collection
    tests = [test for test in session.tests if test.name not in ('test_fixure_1', 'test_fixure_2')]
    for test in tests:
        if test.keywords.get('skip', False):
            session.skip(test)
    if not config.getbool('junit-xml'):
        for test in tests:
            if test.keywords.get('skip', False):
                session.skip(test)
    for test in tests:
        if test.keywords.get('skip', False):
            continue
        if test.name in ('test_fixure_1', 'test_fixure_2'):
            session.add_performance_marker(pytest.mark.last, test.name)

def pytest_runtest_session(session, test_id, test_input):
    # Reorder tests based on last marker
    for i, test in enumerate(session.tests):
        if test.keywords.get('skip', False):
            continue
        if test.name in ('test_fixure_1', 'test_fixure_2'):
            session.tests.insert(i + 1, test)
        elif test.name in ['test_fixure_1_with_last', 'test_fixure_2_with_last']:
            session.tests.append(test)
    return session
