```python
from flask import Flask
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50))

class UserService:
    def get_all(self):
        return User.query.all()

    def get_by_id(self, id):
        return User.query.get(id)

    def create(self, name):
        user = User(name=name)
        db.session.add(user)
        db.session.commit()

user_service = UserService()

@app.route('/users')
def get_users():
    users = user_service.get_all()
    return jsonify([user.name for user in users])

@app.route('/users/<int:id>') 
def get_user(id):
    user = user_service.get_by_id(id)
    return jsonify(user.name)

@app.route('/users', methods=['POST'])
def create_user():
    name = request.form.get('name')
    user_service.create(name)
    return 'User created!'

if __name__ == '__main__':
    app.run(debug=True) 
```

This app:

- Uses Flask-SQLAlchemy to connect to a SQLite database
- Defines a User model mapped to a users table
- Creates a UserService class to handle business logic 
- The /users endpoint calls the service layer to get all users
- The /users/id endpoint calls the service to get a single user by ID
- The POST /users endpoint calls the service to create a new user

